/* A polygon hit produced by the background-collision system.
 *
 * ROM RTTI records dBgPc as the sole base. dBgPi introduces the hierarchy's
 * first virtual function, so mwccarm places its vptr at 0x00 and dBgPc at
 * 0x04. The remaining fields begin at 0x18. This is the layout generated by
 * the pinned compiler and the one used by the C1/C2/D1 ROM bodies.
 */
#ifndef DBGPI_H
#define DBGPI_H
#include "dBgPc.h"

#ifndef __cplusplus

struct dBgPi {
    void **vtable;          /* 0x000 */
    struct dBgPc base;      /* 0x004 */
    u16 triangleID;         /* 0x018 */
    u16 flags;              /* 0x01a */
    s32 clsnID;             /* 0x01c */
    s32 unk_020;            /* 0x020 */
    s32 unk_024;            /* 0x024 */
};

typedef char dBgPi_size_must_be_0x28[sizeof(struct dBgPi) == 0x28 ? 1 : -1];
typedef struct dBgPi dBgPi;

#else

struct dBgPi : dBgPc {
    /* 0x00 is the vptr; the dBgPc base occupies 0x04..0x17. */
    u16 triangleID;         /* 0x018 */
    u16 flags;              /* 0x01a */
    s32 clsnID;             /* 0x01c */
    s32 unk_020;            /* 0x020 */
    s32 unk_024;            /* 0x024 */

    /* --- vtable, in ROM order. Do not reorder. --- */
    virtual ~dBgPi();       /* slots 0 (D1), 1 (D0) */

    /* Defined out of line; objisolate retains the enrolled C1/D1 variants and
       the compiler-generated siblings remain separately enrolled shells. */
    dBgPi();

    /* methods */
    dBgPi &operator=(const dBgPi &other);
    void CopyTo(dBgPi &dst) const;
    u32 GetClsnID() const;
};

/* Size is the dBgPi's own span AND the stride of the three consecutive results
   dBgCh_SphCrr holds at 0x74/0x9c/0xc4 -- notes/collision-system.md 3.2. */
typedef char dBgPi_size_must_be_0x28[sizeof(struct dBgPi) == 0x28 ? 1 : -1];

#endif /* __cplusplus */

#endif
